CREATE OR REPLACE FUNCTION public.clear_runtime_mcp_overlay_on_terminal_state()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    IF NEW.status IN ('completed', 'failed', 'cancelled')
       AND OLD.status IS DISTINCT FROM NEW.status
       AND (NEW.runtime_mcp_overlay IS NOT NULL OR NEW.runtime_connected_apps IS NOT NULL) THEN
        NEW.runtime_mcp_overlay := NULL;
        NEW.runtime_connected_apps := NULL;
    END IF;
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.multica_advance_task_state_version()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    NEW.state_version := OLD.state_version + 1;
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.multica_track_task_queue_time()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    IF TG_OP='INSERT' THEN
        IF NEW.status='queued' THEN
            NEW.queued_at := NEW.created_at;
            NEW.queued_at_source := 'transition';
        END IF;
    ELSIF NEW.status='queued' AND OLD.status IS DISTINCT FROM NEW.status THEN
        NEW.queued_at := now();
        NEW.queued_at_source := 'transition';
    END IF;
    RETURN NEW;
END;
$function$
